import React, { useState } from 'react';

// Define the State interface here
interface State {
  count: number;
}

// Define action types here

// Create action creator functions here

// Create the App component here
function App() {
  // Initialize state here
  const [state, setState] = useState<State>({ count: 0 });

  // Create reducer function here
  const reducer = (state: State, action: any): State => {
    return state;
  };

  // Create dispatch function here
  const dispatch = (action: any) => {
    const newState = reducer(state, action);
    setState(newState);
  };

  return (
    <div className="app">
      <h1>Mini Redux</h1>
      <p>Current count: {state.count}</p>
      <button onClick={() => dispatch({ type: 'INCREMENT' })}>
        Increment
      </button>
      {/* Add decrement button here */}
    </div>
  );
}

export default App;
